import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class SemVerParser {

    private static final Pattern TAG = Pattern.compile(
            "^v(?<major>\\d+)\\.(?<minor>\\d+)\\.(?<patch>\\d+)(?:-(?<label>[A-Za-z0-9.]+))?$");

    public static String describe(String version) {
        if (version == null) {
            return null;
        }
        Matcher m = TAG.matcher(version);
        if (!m.matches()) {
            return null;
        }
        String result = m.group("major") + "|" + m.group("minor") + "|" + m.group("patch");
        String label = m.group("label");
        if (label != null) {
            result = result + "|" + label;
        }
        return result;
    }

    public static int major(String version) {
        if (version == null) {
            return -1;
        }
        Matcher m = TAG.matcher(version);
        if (!m.matches()) {
            return -1;
        }
        return Integer.parseInt(m.group("major"));
    }
}
